"""
Additional corpus documents for HealRAG: United States health-data law and guidance, plus further
EU and UK provisions.

Same document schema as seeder.AUTHORITATIVE_CORPUS. IDs start at doc_108, immediately after the last
synthetic FHIR patient record (doc_033..doc_107), so every pre-existing corpus filename is unchanged.

The text of each entry is a condensed summary written for retrieval, not the binding legal text. Each entry
links to the authoritative source in `source_url`.
"""
import re

ECFR = "https://www.ecfr.gov/current/title-45/section-"

# chunker.chunk_text() starts a new chunk before every "Article N", "Section N" and "Chapter X" it finds, which suits
# one-provision-per-document texts but shatters prose that merely cross-references other provisions. A marker is
# therefore kept only in the opening title phrase (as in the existing docs, e.g. "GDPR Article 5 - ...") and any
# later mention is abbreviated, so each document below is chunked by length rather than by its cross-references.
_MARKER = re.compile(r"\b(Article|Section|Chapter)(\s+)(?=[IVXLCDM\d])", re.IGNORECASE)
_ABBREV = {"article": "Art.", "section": "s.", "chapter": "Ch."}
_TITLE_PREFIX_CHARS = 60


def _protect_cross_references(text):
    head, tail = text[:_TITLE_PREFIX_CHARS], text[_TITLE_PREFIX_CHARS:]
    return head + _MARKER.sub(lambda m: _ABBREV[m.group(1).lower()] + " ", tail)


def _doc(num, slug, title, publisher, jurisdiction, doc_type, published, effective, version, article, url, content):
    return {
        "id": f"doc_{num:03d}_{slug}",
        "title": title,
        "publisher": publisher,
        "jurisdiction": jurisdiction,
        "document_type": doc_type,
        "publication_date": published,
        "effective_from": effective,
        "version": version,
        "article": article,
        "source_url": url,
        "content": _protect_cross_references(content),
    }


# =============================================================================
# United States
# =============================================================================
US_CORPUS = [
    # ---- Overview / definitions (definitional queries such as "What is HIPAA?") ----
    _doc(108, "hipaa_overview", "Overview - What is HIPAA (Health Insurance Portability and Accountability Act)",
         "HealRAG corpus summary of HIPAA", "US", "secondary_commentary", "1996-08-21", "1996-08-21",
         "Pub. L. 104-191", "Overview", "https://www.hhs.gov/hipaa/index.html",
         "Overview - What is HIPAA: The Health Insurance Portability and Accountability Act of 1996 (HIPAA, Public Law 104-191) is the United States federal law that protects the privacy and security of individually identifiable health information. "
         "Its implementing rules are in 45 CFR Parts 160 and 164: the Privacy Rule (Part 164 Subpart E), the Security Rule (Part 164 Subpart C), the Breach Notification Rule (Part 164 Subpart D) and the Enforcement Rule (Part 160). "
         "HIPAA applies to covered entities (health plans, health care clearinghouses and health care providers that transmit health information electronically in standard transactions) and to their business associates. "
         "The protected information is called protected health information (PHI): individually identifiable health information held or transmitted by a covered entity or business associate in any form. "
         "The HHS Office for Civil Rights (OCR) enforces HIPAA. The HITECH Act of 2009 strengthened it with breach notification duties, direct liability for business associates and higher penalties. "
         "Unlike the GDPR, HIPAA is sectoral: it does not cover every organisation that holds health data, so health apps and other non-covered entities fall under other laws such as the FTC Health Breach Notification Rule and state privacy laws. "
         "This is a summary for orientation; the binding text is in 45 CFR Parts 160 and 164."),
    _doc(109, "hipaa_definitions_160_103", "HIPAA Definitions - Covered Entity, Business Associate and PHI (45 CFR 160.103)",
         "eCFR / HHS", "US", "primary_law", "2013-01-25", "2013-03-26", "45 CFR 160.103 (as amended 2013)",
         "45 CFR 160.103", ECFR + "160.103",
         "HIPAA Definitions, 45 CFR 160.103: A covered entity is (1) a health plan, (2) a health care clearinghouse, or (3) a health care provider who transmits any health information in electronic form in connection with a standard transaction covered by HIPAA. "
         "A business associate is a person or organisation that, on behalf of a covered entity, creates, receives, maintains or transmits protected health information for a regulated function or provides certain services (legal, actuarial, accounting, consulting, data aggregation, management, administrative, accreditation or financial) involving PHI. "
         "Subcontractors that handle PHI for a business associate are themselves business associates. "
         "Protected health information (PHI) is individually identifiable health information transmitted or maintained in electronic or any other form or medium, with limited exceptions such as education records and employment records held by a covered entity as employer. "
         "Individually identifiable health information relates to a person's past, present or future physical or mental health, the provision of health care to the person, or payment for that care, and identifies the person or could reasonably be used to identify them. "
         "Information that is de-identified under 45 CFR 164.514 is not PHI."),

    # ---- Privacy Rule ----
    _doc(110, "hipaa_privacy_164_502", "HIPAA Privacy Rule - Uses and Disclosures of PHI: General Rules and Minimum Necessary (45 CFR 164.502)",
         "eCFR / HHS", "US", "primary_law", "2013-01-25", "2013-03-26", "45 CFR 164.502 (as amended 2013)",
         "45 CFR 164.502", ECFR + "164.502",
         "HIPAA Privacy Rule, 45 CFR 164.502 (general rules): A covered entity or business associate may not use or disclose protected health information except as the Privacy Rule permits or requires. "
         "It must disclose PHI to the individual when they request access (164.524) and to HHS when it investigates compliance. "
         "It may use or disclose PHI for treatment, payment and health care operations (164.506), with a valid authorization (164.508), or for the public-interest purposes listed in 164.512. "
         "Minimum necessary standard (164.502(b)): when using or disclosing PHI or requesting it from another entity, a covered entity must make reasonable efforts to limit PHI to the minimum necessary to accomplish the intended purpose. "
         "The minimum necessary standard does not apply to disclosures to a health care provider for treatment, to the individual, to disclosures made under an authorization, to disclosures to HHS, or to uses and disclosures required by law. "
         "Psychotherapy notes receive stronger protection and generally require specific authorization. A covered entity may disclose PHI to a business associate only under a written business associate contract (164.502(e), 164.504(e))."),
    _doc(111, "hipaa_privacy_164_506", "HIPAA Privacy Rule - Treatment, Payment and Health Care Operations (45 CFR 164.506)",
         "eCFR / HHS", "US", "primary_law", "2013-01-25", "2013-03-26", "45 CFR 164.506 (as amended 2013)",
         "45 CFR 164.506", ECFR + "164.506",
         "HIPAA Privacy Rule, 45 CFR 164.506 (uses and disclosures for treatment, payment and health care operations, often shortened to TPO): A covered entity may use and disclose PHI for its own treatment, payment or health care operations without the individual's authorization. "
         "Treatment means providing, coordinating or managing health care, including consultations and referrals between providers. "
         "Payment covers activities such as billing, claims management, determining eligibility and coverage, and utilisation review. "
         "Health care operations include quality assessment and improvement, competency review and training, accreditation, medical review, legal services, auditing, and business planning and management. "
         "A covered entity may also disclose PHI for another covered entity's treatment and payment activities, and for certain health care operations of the recipient if both have a relationship with the individual and the disclosure is for quality or fraud-related purposes. "
         "Consent for TPO is optional under HIPAA: a covered entity may choose to seek the individual's consent, but is not required to. Disclosures for TPO remain subject to the minimum necessary standard, except for treatment disclosures between providers."),
    _doc(112, "hipaa_privacy_164_508", "HIPAA Privacy Rule - Authorization for Uses and Disclosures (45 CFR 164.508)",
         "eCFR / HHS", "US", "primary_law", "2013-01-25", "2013-03-26", "45 CFR 164.508 (as amended 2013)",
         "45 CFR 164.508", ECFR + "164.508",
         "HIPAA Privacy Rule, 45 CFR 164.508 (authorization): A covered entity must obtain a valid written authorization for any use or disclosure of PHI that the Privacy Rule does not otherwise permit, including most marketing, any sale of PHI, and uses and disclosures of psychotherapy notes. "
         "A valid authorization must be in plain language and contain: a specific and meaningful description of the information; who may disclose it; who may receive it; the purpose; an expiration date or event; the individual's signature and date; a statement of the right to revoke in writing; a statement that treatment, payment, enrolment or eligibility generally cannot be conditioned on signing; and a statement that information disclosed may be redisclosed and no longer protected by HIPAA. "
         "An individual may revoke an authorization in writing at any time, except to the extent the covered entity has already acted in reliance on it. "
         "Marketing authorizations must disclose any financial remuneration. A sale of PHI requires an authorization stating that the disclosure will result in remuneration. "
         "A covered entity must give the individual a copy of the signed authorization and keep it for six years."),
    _doc(113, "hipaa_privacy_164_512", "HIPAA Privacy Rule - Disclosures Without Authorization: Public Health, Research, Law Enforcement (45 CFR 164.512)",
         "eCFR / HHS", "US", "primary_law", "2013-01-25", "2013-03-26", "45 CFR 164.512 (as amended 2013)",
         "45 CFR 164.512", ECFR + "164.512",
         "HIPAA Privacy Rule, 45 CFR 164.512 (uses and disclosures for which authorization or an opportunity to agree or object is not required): A covered entity may use or disclose PHI without the individual's authorization for twelve public-interest purposes, subject to conditions. "
         "They are: required by law; public health activities (preventing or controlling disease, reporting births and deaths, child abuse reporting, FDA-regulated product safety, and notifying people exposed to a communicable disease); victims of abuse, neglect or domestic violence; health oversight activities; judicial and administrative proceedings; law enforcement purposes; decedents (coroners, medical examiners, funeral directors); organ and tissue donation; research; serious threats to health or safety; specialised government functions; and workers' compensation. "
         "Research (164.512(i)): PHI may be used for research without authorization if an Institutional Review Board (IRB) or Privacy Board approves a waiver or alteration of authorization, if the use is preparatory to research, or if it concerns research on decedents. "
         "The waiver criteria require that the use involves no more than minimal privacy risk, that the research could not practicably be done without the waiver, and that it could not practicably be done without the PHI. "
         "Most 164.512 disclosures are subject to the minimum necessary standard."),
    _doc(114, "hipaa_privacy_164_514", "HIPAA Privacy Rule - De-identification: Safe Harbor and Expert Determination (45 CFR 164.514)",
         "eCFR / HHS", "US", "primary_law", "2013-01-25", "2013-03-26", "45 CFR 164.514 (as amended 2013)",
         "45 CFR 164.514(a)-(b)", ECFR + "164.514",
         "HIPAA Privacy Rule, 45 CFR 164.514(a)-(b) (de-identification): Health information is not PHI, and HIPAA no longer restricts its use, once it has been de-identified by one of two methods. "
         "Expert Determination (164.514(b)(1)): a person with appropriate knowledge of and experience with statistical and scientific methods for rendering information not individually identifiable applies those methods and documents that the risk of identifying an individual is very small. "
         "Safe Harbor (164.514(b)(2)): remove all eighteen identifiers of the individual and of relatives, employers and household members, and the covered entity has no actual knowledge that the remaining information could identify the individual. "
         "The eighteen identifiers are: names; geographic subdivisions smaller than a state (with limited use of the first three digits of a ZIP code for areas over 20,000 people); all elements of dates except year, and ages over 89; telephone numbers; fax numbers; email addresses; Social Security numbers; medical record numbers; health plan beneficiary numbers; account numbers; certificate and licence numbers; vehicle identifiers and licence plates; device identifiers and serial numbers; URLs; IP addresses; biometric identifiers including finger and voice prints; full-face photographs and comparable images; and any other unique identifying number, characteristic or code. "
         "A limited data set (164.514(e)) removes direct identifiers but may keep dates and some geography; it may be used for research, public health and health care operations under a data use agreement."),
    _doc(115, "hipaa_privacy_164_520_524", "HIPAA Privacy Rule - Notice of Privacy Practices and Individual Right of Access (45 CFR 164.520, 164.524)",
         "eCFR / HHS", "US", "primary_law", "2013-01-25", "2013-03-26", "45 CFR 164.520 and 164.524 (as amended 2013)",
         "45 CFR 164.520, 164.524", ECFR + "164.524",
         "HIPAA Privacy Rule individual rights: Notice of Privacy Practices (45 CFR 164.520): most covered entities must give individuals a plain-language notice describing how PHI may be used and disclosed, the individual's rights, and the entity's legal duties, and must make a good-faith effort to obtain written acknowledgement of receipt from direct treatment providers. "
         "Right of access (45 CFR 164.524): individuals have the right to inspect and obtain a copy of PHI in a designated record set, including medical and billing records, and to direct that a copy be sent to a third party they designate. "
         "A covered entity must act on an access request within 30 days, with one 30-day extension if it gives the individual a written reason and a date. "
         "If the PHI is kept electronically, the individual may ask for an electronic copy in the form and format requested if readily producible. "
         "A covered entity may charge only a reasonable, cost-based fee covering labour for copying, supplies, postage and a summary if agreed, and may not charge for searching or retrieval. "
         "Access may be denied only for limited reasons, such as psychotherapy notes or information compiled for legal proceedings, and certain denials are reviewable."),
    _doc(116, "hipaa_privacy_164_526_528", "HIPAA Privacy Rule - Right to Amend and Accounting of Disclosures (45 CFR 164.526, 164.528)",
         "eCFR / HHS", "US", "primary_law", "2013-01-25", "2013-03-26", "45 CFR 164.526 and 164.528 (as amended 2013)",
         "45 CFR 164.526, 164.528", ECFR + "164.526",
         "HIPAA Privacy Rule individual rights, continued: Right to amend (45 CFR 164.526): an individual may ask a covered entity to amend PHI in a designated record set that is inaccurate or incomplete. "
         "The covered entity must act within 60 days, with one 30-day extension, and may deny the request if it did not create the information, if the information is not part of the designated record set, is not available for inspection, or is accurate and complete. "
         "If it denies, the individual may submit a statement of disagreement that becomes part of the record. "
         "Accounting of disclosures (45 CFR 164.528): an individual may request a list of certain disclosures of their PHI made in the six years before the request. "
         "The accounting excludes disclosures for treatment, payment and health care operations, disclosures to the individual, disclosures made under an authorization, and incidental disclosures. "
         "The covered entity must respond within 60 days. Other rights include the right to request restrictions (164.522(a)), including the right to restrict disclosures to a health plan when the individual pays out of pocket in full, and the right to confidential communications (164.522(b))."),
    _doc(117, "hipaa_business_associates_164_504e", "HIPAA Business Associates and Business Associate Agreements (45 CFR 164.502(e), 164.504(e), 164.308(b))",
         "eCFR / HHS", "US", "primary_law", "2013-01-25", "2013-09-23", "45 CFR 164.504(e) (as amended 2013)",
         "45 CFR 164.504(e)", ECFR + "164.504",
         "HIPAA business associate agreements (BAAs), 45 CFR 164.502(e), 164.504(e) and 164.308(b): A covered entity may let a business associate create, receive, maintain or transmit PHI on its behalf only if it obtains satisfactory assurances, in a written contract, that the business associate will appropriately safeguard the information. "
         "A BAA must: establish the permitted and required uses and disclosures; prohibit uses or disclosures that would violate the Privacy Rule if done by the covered entity; require appropriate safeguards and compliance with the Security Rule's requirements for electronic PHI; require reporting of unauthorised uses and disclosures, including breaches of unsecured PHI and security incidents; require the business associate to bind its subcontractors to the same restrictions; make PHI available to support the individual's rights of access, amendment and accounting; make books and records available to HHS; and require return or destruction of PHI at termination if feasible. "
         "Since the 2013 Omnibus Rule and the HITECH Act, business associates are directly liable for Security Rule compliance, for impermissible uses and disclosures, for failing to provide breach notification to the covered entity, and for failing to enter BAAs with their subcontractors."),

    # ---- Security Rule ----
    _doc(118, "hipaa_security_164_306_308", "HIPAA Security Rule - General Requirements and Administrative Safeguards (45 CFR 164.306, 164.308)",
         "eCFR / HHS", "US", "primary_law", "2003-02-20", "2005-04-20", "45 CFR 164.306 and 164.308",
         "45 CFR 164.306, 164.308", ECFR + "164.308",
         "HIPAA Security Rule, 45 CFR 164.306 and 164.308: Covered entities and business associates must ensure the confidentiality, integrity and availability of all electronic protected health information (ePHI) they create, receive, maintain or transmit, protect against reasonably anticipated threats and hazards, protect against impermissible uses or disclosures, and ensure workforce compliance. "
         "Implementation specifications are either required or addressable; addressable does not mean optional, and the entity must implement the specification, an equivalent alternative, or document why neither is reasonable. "
         "Administrative safeguards (164.308) include: security management process with a risk analysis, risk management, sanction policy and information system activity review (164.308(a)(1)); an assigned security official; workforce security and information access management; security awareness and training; security incident procedures; contingency plan with data backup, disaster recovery and emergency mode operation plans; periodic evaluation; and business associate contracts. "
         "The risk analysis is an accurate and thorough assessment of the potential risks and vulnerabilities to the confidentiality, integrity and availability of ePHI, and is the most frequently cited failure in OCR enforcement actions."),
    _doc(119, "hipaa_security_164_310", "HIPAA Security Rule - Physical Safeguards (45 CFR 164.310)",
         "eCFR / HHS", "US", "primary_law", "2003-02-20", "2005-04-20", "45 CFR 164.310",
         "45 CFR 164.310", ECFR + "164.310",
         "HIPAA Security Rule physical safeguards, 45 CFR 164.310: Covered entities and business associates must implement physical measures, policies and procedures to protect electronic information systems and related buildings and equipment from natural and environmental hazards and unauthorised intrusion. "
         "Standards: facility access controls (contingency operations, facility security plan, access control and validation procedures, maintenance records); workstation use, which specifies the proper functions and physical surroundings of workstations that access ePHI; workstation security, restricting physical access to authorised users; and device and media controls, covering disposal and media re-use of hardware and electronic media that hold ePHI, accountability through records of hardware and media movements, and data backup and storage before equipment is moved."),
    _doc(120, "hipaa_security_164_312", "HIPAA Security Rule - Technical Safeguards: Access Control, Audit, Integrity, Transmission Security (45 CFR 164.312)",
         "eCFR / HHS", "US", "primary_law", "2003-02-20", "2005-04-20", "45 CFR 164.312",
         "45 CFR 164.312", ECFR + "164.312",
         "HIPAA Security Rule technical safeguards, 45 CFR 164.312: Covered entities and business associates must implement technology and related policies that protect ePHI and control access to it. "
         "Standards: access control, with unique user identification and emergency access procedure as required specifications, and automatic logoff and encryption and decryption as addressable specifications; audit controls, meaning hardware, software and procedural mechanisms that record and examine activity in systems containing ePHI; integrity, protecting ePHI from improper alteration or destruction, with a mechanism to authenticate ePHI; person or entity authentication, verifying that the person seeking access is who they claim to be; and transmission security, guarding against unauthorised access to ePHI sent over a network, with integrity controls and encryption as addressable specifications. "
         "The Security Rule is technology-neutral and does not mandate specific products, but HHS guidance treats encryption that meets NIST standards as the way to render PHI unusable, unreadable or indecipherable and thereby qualify for the breach-notification safe harbor."),

    # ---- Breach notification ----
    _doc(121, "hipaa_breach_164_402", "HIPAA Breach Notification Rule - Definition of Breach and Risk Assessment (45 CFR 164.402)",
         "eCFR / HHS", "US", "primary_law", "2013-01-25", "2013-09-23", "45 CFR 164.402 (Omnibus Rule 2013)",
         "45 CFR 164.402", ECFR + "164.402",
         "HIPAA Breach Notification Rule, 45 CFR 164.402: A breach is the acquisition, access, use or disclosure of PHI in a manner not permitted by the Privacy Rule that compromises the security or privacy of the PHI. "
         "An impermissible use or disclosure is presumed to be a breach unless the covered entity or business associate demonstrates a low probability that the PHI has been compromised, based on a risk assessment of at least four factors: (1) the nature and extent of the PHI involved, including the types of identifiers and the likelihood of re-identification; (2) the unauthorised person who used the PHI or to whom it was disclosed; (3) whether the PHI was actually acquired or viewed; and (4) the extent to which the risk has been mitigated. "
         "Exceptions include unintentional good-faith access by a workforce member, inadvertent disclosure between authorised persons at the same entity, and disclosures where the recipient could not reasonably have retained the information. "
         "Notification duties apply only to unsecured PHI, which is PHI not rendered unusable, unreadable or indecipherable to unauthorised persons through encryption or destruction in line with HHS guidance."),
    _doc(122, "hipaa_breach_164_404_408", "HIPAA Breach Notification Rule - Notice to Individuals, HHS and the Media: 60-Day Deadline (45 CFR 164.404-164.410)",
         "eCFR / HHS", "US", "primary_law", "2013-01-25", "2013-09-23", "45 CFR 164.404, 164.406, 164.408, 164.410",
         "45 CFR 164.404-164.410", ECFR + "164.404",
         "HIPAA breach notification deadlines, 45 CFR 164.404 to 164.410: After discovering a breach of unsecured PHI, a covered entity must notify each affected individual without unreasonable delay and in no case later than 60 calendar days after discovery. "
         "A breach is treated as discovered on the first day it is known, or would have been known with reasonable diligence, to the covered entity. "
         "The notice, by first-class mail or email if the individual agreed, must describe what happened and the dates, the types of PHI involved, steps individuals should take, what the entity is doing to investigate and mitigate, and contact procedures. "
         "Media notice (164.406): if a breach affects more than 500 residents of a state or jurisdiction, the covered entity must notify prominent media outlets in that area within 60 days. "
         "Notice to the HHS Secretary (164.408): for breaches affecting 500 or more individuals, notify HHS at the same time as individuals and no later than 60 days after discovery; for breaches affecting fewer than 500, keep a log and report to HHS within 60 days after the end of the calendar year in which the breach was discovered. "
         "Business associates (164.410) must notify the covered entity without unreasonable delay and no later than 60 days after discovery. Law enforcement may request a delay. The burden of proof lies with the entity to show that required notifications were made."),
    _doc(123, "hipaa_enforcement_penalties", "HIPAA Enforcement - Civil Penalty Tiers and Criminal Penalties (45 CFR 160.404, 42 USC 1320d-5, 1320d-6)",
         "HHS Office for Civil Rights", "US", "primary_law", "2009-02-17", "2009-02-18", "HITECH Act s.13410; 45 CFR 160.404",
         "45 CFR 160.404; 42 USC 1320d-5, 1320d-6", "https://www.hhs.gov/hipaa/for-professionals/compliance-enforcement/index.html",
         "HIPAA penalty tiers: Civil money penalties under 45 CFR 160.404 and 42 USC 1320d-5 are set in four tiers according to culpability: (1) the entity did not know and, by exercising reasonable diligence, would not have known of the violation; (2) reasonable cause, but not willful neglect; (3) willful neglect that was corrected within 30 days; (4) willful neglect that was not corrected. "
         "Each tier has a minimum and maximum amount per violation and an annual cap for identical violations; the amounts are adjusted for inflation each year, and HHS applies lower annual caps for the lower tiers under its 2019 notice of enforcement discretion. "
         "The HITECH Act extended these penalties to business associates and required HHS to investigate complaints involving willful neglect. State attorneys general may also bring civil actions for HIPAA violations. "
         "Criminal penalties under 42 USC 1320d-6, enforced by the Department of Justice: knowingly obtaining or disclosing PHI in violation of HIPAA carries up to $50,000 and one year in prison; offences committed under false pretences carry up to $100,000 and five years; offences committed with intent to sell, transfer or use PHI for commercial advantage, personal gain or malicious harm carry up to $250,000 and ten years. "
         "OCR commonly resolves cases through resolution agreements with corrective action plans, typically running two to three years, as well as civil money penalties."),
    _doc(124, "hitech_act", "HITECH Act 2009 - Breach Notification, Business Associate Liability and Meaningful Use",
         "US Congress / HHS", "US", "primary_law", "2009-02-17", "2009-02-17", "Pub. L. 111-5, Title XIII",
         "HITECH Act Title XIII", "https://www.hhs.gov/hipaa/for-professionals/special-topics/hitech-act-enforcement-interim-final-rule/index.html",
         "HITECH Act (Health Information Technology for Economic and Clinical Health Act), enacted 17 February 2009 as Title XIII of the American Recovery and Reinvestment Act: Promoted adoption of electronic health records through Medicare and Medicaid incentive payments (the Meaningful Use programme, later Promoting Interoperability). "
         "Strengthened HIPAA by: creating the first federal breach notification requirements for covered entities and business associates; making business associates directly subject to the Security Rule and parts of the Privacy Rule; prohibiting the sale of PHI without authorization and restricting marketing uses; giving individuals the right to an electronic copy of PHI held in an electronic health record and to restrict disclosures to a health plan for services paid in full out of pocket; and establishing tiered civil penalties and state attorney general enforcement. "
         "The 2013 HIPAA Omnibus Rule implemented most of these HITECH provisions in the HIPAA regulations. HITECH also created the HHS Office of the National Coordinator for Health Information Technology (ONC) in statute, and in 2016 the 21st Century Cures Act added the information blocking prohibition."),

    # ---- Other federal law ----
    _doc(125, "us_42cfr_part2_sud_records", "42 CFR Part 2 - Confidentiality of Substance Use Disorder Patient Records",
         "SAMHSA / HHS", "US", "primary_law", "2024-02-16", "2024-04-16", "42 CFR Part 2 (2024 Final Rule)",
         "42 CFR Part 2", "https://www.ecfr.gov/current/title-42/chapter-I/subchapter-A/part-2",
         "42 CFR Part 2: Federal rules, issued under 42 USC 290dd-2, that protect the confidentiality of records of patients treated by federally assisted substance use disorder (SUD) programmes. "
         "Part 2 is stricter than HIPAA: SUD treatment records generally may not be disclosed, or used in civil, criminal, administrative or legislative proceedings against the patient, without the patient's written consent or a specific court order meeting Part 2 criteria. "
         "The 2024 Final Rule, implementing the CARES Act of 2020, aligns Part 2 more closely with HIPAA: a patient may give a single consent for all future uses and disclosures for treatment, payment and health care operations; HIPAA covered entities and business associates that receive Part 2 records under that consent may redisclose them as HIPAA permits; breach notification now applies to Part 2 records; and the rule adopts HIPAA-style civil and criminal penalties. "
         "The rule took effect on 16 April 2024 and entities had to comply by 16 February 2026. Patients also gain rights to an accounting of disclosures and to request restrictions, and new protections cover use of the records in legal proceedings."),
    _doc(126, "us_cures_act_information_blocking", "21st Century Cures Act - Information Blocking Prohibition (45 CFR Part 171)",
         "ASTP/ONC / HHS", "US", "primary_law", "2020-05-01", "2021-04-05", "45 CFR Part 171",
         "45 CFR Part 171", "https://www.ecfr.gov/current/title-45/subtitle-A/subchapter-D/part-171",
         "Information blocking, 21st Century Cures Act s.4004 and 45 CFR Part 171: Information blocking is a practice that is likely to interfere with access, exchange or use of electronic health information (EHI), except as required by law or covered by an exception. "
         "It applies to three types of actors: health care providers; health IT developers of certified health IT; and health information exchanges and health information networks. "
         "For providers, the practice must be one the provider knows is unreasonable and likely to interfere; for developers, exchanges and networks, they know or should know it is likely to interfere. "
         "Exceptions fall into those that involve not fulfilling a request (preventing harm, privacy, security, infeasibility, health IT performance) and those that involve procedures for fulfilling a request (content and manner, fees, licensing). The 2024 HTI-1 final rule added further exceptions, including one for TEFCA manner. "
         "Penalties differ by actor: developers, exchanges and networks face civil money penalties of up to $1 million per violation, enforced by the HHS Office of Inspector General; providers face appropriate disincentives set by CMS programmes, such as loss of Medicare Promoting Interoperability credit. "
         "Since 2022 the EHI covered is all electronic protected health information in a designated record set, not just the USCDI data elements."),
    _doc(127, "us_ftc_health_breach_notification_rule", "FTC Health Breach Notification Rule for Health Apps and Non-HIPAA Entities (16 CFR Part 318)",
         "Federal Trade Commission", "US", "primary_law", "2024-05-30", "2024-07-29", "16 CFR Part 318 (2024 amendments)",
         "16 CFR Part 318", "https://www.ecfr.gov/current/title-16/chapter-I/subchapter-C/part-318",
         "FTC Health Breach Notification Rule, 16 CFR Part 318: Applies to vendors of personal health records, PHR-related entities and their third-party service providers that are not covered by HIPAA, including many health and wellness apps, connected devices and websites. "
         "The 2024 amendments, effective 29 July 2024, clarify that the rule covers health apps and similar technologies; that a breach of security includes unauthorised disclosure, such as sharing health data with advertisers without the user's authorisation, not only a cyberattack; and that PHR identifiable health information includes data drawn from multiple sources, including a user's device. "
         "After discovering a breach, a covered entity must notify affected individuals and the FTC without unreasonable delay and within 60 calendar days; for breaches affecting 500 or more people the FTC must be notified at the same time as individuals, and for fewer than 500 within the same 60-day window through an annual log. Media notice is required if more than 500 residents of a state are affected. "
         "Violations are treated as unfair or deceptive acts under the FTC Act, with civil penalties per violation. The FTC has used the rule against GoodRx and Premom, among others. FTC Act section 5 also applies to deceptive health privacy claims."),
    _doc(128, "us_common_rule_45cfr46", "Common Rule - Protection of Human Subjects in Research: IRB Review and Informed Consent (45 CFR Part 46)",
         "HHS Office for Human Research Protections", "US", "primary_law", "2017-01-19", "2019-01-21", "45 CFR Part 46 Subpart A (Revised Common Rule 2018)",
         "45 CFR 46", "https://www.ecfr.gov/current/title-45/subtitle-A/subchapter-A/part-46",
         "Common Rule, 45 CFR Part 46 Subpart A (Federal Policy for the Protection of Human Subjects): Applies to research involving human subjects conducted or supported by federal departments and agencies that have adopted it. "
         "Research must be reviewed by an Institutional Review Board (IRB), which approves it only if risks are minimised and reasonable in relation to anticipated benefits, subject selection is equitable, informed consent is sought and documented, and there are adequate provisions to protect privacy and confidentiality. "
         "The Revised Common Rule, effective 21 January 2019, requires informed consent to begin with a concise summary of key information, introduces broad consent for storage and secondary research use of identifiable private information and biospecimens, requires single IRB review for most multi-site studies, and adds exemptions for secondary research with identifiable information if the data are publicly available, recorded so subjects cannot be readily identified, or regulated by HIPAA as health care operations, research or public health. "
         "A research study may need both IRB review under the Common Rule and compliance with the HIPAA Privacy Rule, which requires an authorization or a waiver for research use of PHI."),
    _doc(129, "us_fda_ai_device_pccp", "FDA - Predetermined Change Control Plans for AI-Enabled Device Software Functions",
         "US Food and Drug Administration", "US", "regulator_guidance", "2024-12-04", "2024-12-04", "Final Guidance, December 2024",
         "PCCP Final Guidance", "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/marketing-submission-recommendations-predetermined-change-control-plan-artificial-intelligence-enabled",
         "FDA regulation of AI in medical devices: Software that meets the definition of a device, including software as a medical device (SaMD), is regulated under the Federal Food, Drug, and Cosmetic Act, and AI-enabled device software functions are typically cleared through 510(k), De Novo or premarket approval. "
         "In December 2024 FDA issued final guidance on Predetermined Change Control Plans (PCCPs) for AI-enabled device software functions. A PCCP, authorised under section 515C of the FD&C Act, lets a manufacturer describe in a marketing submission the specific planned modifications to an AI model, the protocol for developing, validating and implementing them, and an impact assessment. "
         "If FDA authorises the PCCP, the manufacturer may implement the described changes without a new marketing submission. A PCCP has three components: a description of modifications, a modification protocol covering data management, retraining practices, performance evaluation and update procedures, and an impact assessment of benefits and risks. "
         "FDA also expects manufacturers to address transparency, bias and the representativeness of training data across patient populations, and cybersecurity under section 524B of the FD&C Act."),

    # ---- US state law ----
    _doc(130, "us_california_cmia", "California Confidentiality of Medical Information Act (CMIA) - Civil Code 56 et seq.",
         "State of California", "US", "primary_law", "1981-01-01", "1982-01-01", "Cal. Civ. Code s.56 et seq. (as amended)",
         "Civil Code 56-56.37", "https://leginfo.legislature.ca.gov/faces/codes_displayexpand.xhtml?tocCode=CIV&division=1.&title=&part=2.6.&chapter=&article=",
         "California Confidentiality of Medical Information Act (CMIA), Civil Code section 56 et seq.: Prohibits providers of health care, health care service plans and contractors from disclosing medical information about a patient without a valid authorization, except for listed purposes such as treatment, payment, and as required by law. "
         "It is broader than HIPAA in several ways: it applies to any business that offers software or hardware, including mobile apps, designed to maintain medical information so a consumer can manage their information or receive diagnosis, treatment or management of a condition, and treats such businesses as providers of health care. "
         "Amendments extended the law to reproductive and sexual health digital services and to mental health application information. "
         "CMIA provides a private right of action: an individual may sue for nominal damages of $1,000 for a negligent release of medical information without proof of actual harm, plus actual damages, and administrative fines and civil penalties are available for knowing or willful violations. "
         "Information that is HIPAA PHI held by a HIPAA covered entity is largely exempt from the CCPA, but not from the CMIA."),
    _doc(131, "us_california_ccpa_cpra_health", "California Consumer Privacy Act and CPRA - Sensitive Personal Information and Health Data Exemptions",
         "State of California", "US", "primary_law", "2020-11-03", "2023-01-01", "Cal. Civ. Code s.1798.100 et seq. (CCPA as amended by CPRA)",
         "Civil Code 1798.100, 1798.140, 1798.145", "https://cppa.ca.gov/regulations/",
         "California Consumer Privacy Act (CCPA), as amended by the California Privacy Rights Act (CPRA), effective 1 January 2023: gives California residents rights to know, delete, correct, and opt out of the sale or sharing of their personal information, and to limit the use of sensitive personal information. "
         "Sensitive personal information includes personal information collected and analysed concerning a consumer's health, as well as genetic data, biometric information processed to identify a person, precise geolocation, and racial or ethnic origin. "
         "Health data exemptions (Civil Code 1798.145(c)): the CCPA does not apply to protected health information collected by a HIPAA covered entity or business associate, to medical information governed by the CMIA, or to information collected as part of clinical trials subject to the Common Rule. "
         "Consumer health data held by non-HIPAA companies, such as wellness apps and retailers, is covered. Enforcement is by the California Privacy Protection Agency and the Attorney General; consumers have a private right of action only for certain data breaches caused by failure to maintain reasonable security."),
    _doc(132, "us_washington_my_health_my_data_act", "Washington My Health My Data Act (MHMDA) - Consumer Health Data",
         "State of Washington", "US", "primary_law", "2023-04-27", "2024-03-31", "RCW 19.373 (HB 1155)",
         "RCW 19.373", "https://app.leg.wa.gov/RCW/default.aspx?cite=19.373",
         "Washington My Health My Data Act (MHMDA), RCW 19.373, effective 31 March 2024 (30 June 2024 for small businesses): regulates the collection, sharing and sale of consumer health data by entities that are not covered by HIPAA. "
         "Consumer health data is personal information linked or reasonably linkable to a consumer that identifies their past, present or future physical or mental health status, including health conditions, treatments, reproductive and sexual health information, biometric data, genetic data, gender-affirming care, and precise location information that could indicate an attempt to obtain health services. "
         "Requirements: a separate consumer health data privacy policy; opt-in consent to collect consumer health data beyond what is necessary to provide the requested service, and separate consent to share it; a signed valid authorization to sell consumer health data; rights to access, delete and withdraw consent; and restrictions on geofencing within 2,000 feet of facilities that provide in-person health care services. "
         "The Act exempts PHI under HIPAA and certain research and public health information. Violations are enforced by the Attorney General and by a private right of action under the Washington Consumer Protection Act. Nevada and Connecticut enacted similar consumer health data laws."),
    _doc(133, "us_texas_hb300_medical_records_privacy", "Texas Medical Records Privacy Act (HB 300) - Health and Safety Code Chapter 181",
         "State of Texas", "US", "primary_law", "2011-06-17", "2012-09-01", "Tex. Health & Safety Code ch. 181",
         "Chapter 181", "https://statutes.capitol.texas.gov/Docs/HS/htm/HS.181.htm",
         "Texas Medical Records Privacy Act (HB 300), Health and Safety Code Chapter 181: Applies HIPAA-like duties to a broader group than federal HIPAA by defining covered entity to include any person who comes into possession of, obtains, stores or assembles protected health information, including employees and contractors of health care providers, data processors and many non-clinical businesses. "
         "Requirements include: training of employees on Texas and federal privacy law within 90 days of hiring and at least every two years; notice to patients that their PHI is subject to electronic disclosure; a prohibition on selling PHI; a consumer right to receive records in electronic form within 15 business days of a request; and authorisation for most marketing communications. "
         "Texas breach law (Business and Commerce Code chapter 521) separately requires notice to affected individuals without unreasonable delay and within 60 days of discovery, and notice to the Attorney General within 30 days if 250 or more Texas residents are affected. "
         "Civil penalties scale with culpability and are enforced by the Attorney General and licensing agencies, with higher penalties for knowing or intentional violations and for conduct for financial gain."),
    _doc(134, "us_state_privacy_landscape", "US State Privacy Law Landscape for Health Data - Beyond HIPAA",
         "HealRAG corpus summary", "US", "secondary_commentary", "2025-06-01", "2025-06-01", "2025.06",
         "Overview", "https://www.hhs.gov/hipaa/for-professionals/faq/399/does-hipaa-preempt-state-laws/index.html",
         "US state privacy landscape for health data: The United States has no single federal privacy law like the GDPR. HIPAA covers only covered entities and business associates, so consumer health apps, wearables, data brokers and many websites sit outside it. "
         "HIPAA sets a federal floor: state laws that are more stringent, giving individuals greater privacy protection or rights, are not preempted (45 CFR 160.203). "
         "Layers that apply in practice: comprehensive state consumer privacy laws, such as those of California, Virginia, Colorado, Connecticut and Texas, which treat health data as sensitive data requiring opt-in consent or a right to limit, but typically exempt HIPAA PHI; state health-information laws, such as California's CMIA and Texas HB 300; consumer health data laws, such as Washington's My Health My Data Act and Nevada's SB 370; and state breach notification laws, which exist in all 50 states and usually have shorter or different clocks than HIPAA. "
         "Special categories receive extra statutes in many states: HIV status, mental health, substance use disorder records (also 42 CFR Part 2), genetic information and reproductive health. "
         "The FTC applies Section 5 of the FTC Act and its Health Breach Notification Rule to non-HIPAA health data."),

    # ---- US guidance (regulator, rank 2) ----
    _doc(135, "us_hhs_deidentification_guidance", "HHS OCR Guidance on De-identification of PHI (Safe Harbor and Expert Determination)",
         "HHS Office for Civil Rights", "US", "regulator_guidance", "2012-11-26", "2012-11-26", "OCR Guidance 2012",
         "De-identification Guidance", "https://www.hhs.gov/hipaa/for-professionals/special-topics/de-identification/index.html",
         "HHS OCR guidance on methods for de-identification of PHI under 45 CFR 164.514: Explains the two HIPAA methods. Under Safe Harbor, the eighteen listed identifiers must be removed and the entity must not know that the rest could identify an individual; the guidance clarifies that dates must be reduced to year and that ages over 89 must be aggregated into a 90 or older category. "
         "Under Expert Determination, the expert applies statistical or scientific principles to conclude that the risk of identification by an anticipated recipient is very small, and documents the methods and results. The guidance notes that there is no explicit numerical threshold for very small risk and that the expert may take into account replicability, data source availability and distinguishability. "
         "De-identified data can be released without HIPAA restrictions, but re-identification codes derived from patient information are not permitted. Data that is de-identified under HIPAA may still be personal data under the GDPR, which has a different anonymisation standard based on whether identification is reasonably likely by any means."),
    _doc(136, "us_hhs_cloud_computing_guidance", "HHS OCR Guidance on HIPAA and Cloud Computing",
         "HHS Office for Civil Rights", "US", "regulator_guidance", "2016-10-06", "2016-10-06", "OCR Guidance 2016",
         "Cloud Computing Guidance", "https://www.hhs.gov/hipaa/for-professionals/special-topics/health-information-technology/cloud-computing/index.html",
         "HHS OCR guidance on HIPAA and cloud computing: A cloud service provider (CSP) that creates, receives, maintains or transmits ePHI on behalf of a covered entity or business associate is a business associate, and a BAA is required. "
         "This applies even if the CSP stores only encrypted ePHI and does not hold the decryption key, because the CSP still maintains the ePHI. The 'conduit exception' applies only to transmission-only services that do not store PHI other than transiently. "
         "A covered entity may use a CSP to store ePHI outside the United States; HIPAA does not prohibit it, but the risk analysis should account for the additional risks. "
         "A BAA with a CSP should address which security responsibilities fall to the CSP and which to the customer, and the CSP must report security incidents and breaches. Using a CSP that does not sign a BAA with a covered entity violates HIPAA. Mobile device and app use is covered by related OCR guidance."),
    _doc(137, "us_hhs_online_tracking_technologies", "HHS OCR Bulletin on Online Tracking Technologies Used by HIPAA Covered Entities",
         "HHS Office for Civil Rights", "US", "regulator_guidance", "2022-12-01", "2024-03-18", "Bulletin (updated 18 March 2024)",
         "Tracking Technologies Bulletin", "https://www.hhs.gov/hipaa/for-professionals/privacy/guidance/hipaa-online-tracking/index.html",
         "HHS OCR bulletin on online tracking technologies: Issued December 2022 and updated 18 March 2024, it explains that HIPAA covered entities and business associates that use tracking technologies such as cookies, web beacons, pixels and session-replay scripts on websites and mobile apps must comply with the Privacy, Security and Breach Notification Rules when the technology collects PHI. "
         "OCR's position was that on authenticated pages such as patient portals the tracking data is PHI, and that disclosing it to a vendor such as an analytics or advertising company requires a HIPAA-compliant authorization or a BAA with that vendor, and that an impermissible disclosure is a breach. "
         "In June 2024, in American Hospital Association v. Becerra, a federal court in the Northern District of Texas vacated the portion of the bulletin addressing the 'proscribed combination' of an IP address with a visit to an unauthenticated public webpage on a health topic. "
         "The rest of the bulletin, including its treatment of authenticated pages and the BAA requirement, remains. Separately, the FTC and state laws regulate tracking technologies used by organisations outside HIPAA."),
    _doc(138, "us_hhs_security_rule_nprm_2025", "HHS Proposed Update to the HIPAA Security Rule (NPRM, January 2025)",
         "HHS Office for Civil Rights", "US", "regulator_guidance", "2025-01-06", "2025-01-06", "Notice of Proposed Rulemaking, 90 FR 898",
         "Security Rule NPRM", "https://www.federalregister.gov/documents/2025/01/06/2024-30983/hipaa-security-rule-to-strengthen-the-cybersecurity-of-electronic-protected-health-information",
         "HHS proposed update to the HIPAA Security Rule, published 6 January 2025 as a Notice of Proposed Rulemaking (not a final rule): HHS proposed to strengthen the cybersecurity of ePHI by removing the distinction between required and addressable implementation specifications, so that almost all would be required. "
         "Proposed new requirements include: a written technology asset inventory and network map reviewed at least every 12 months; a more specific risk analysis; multi-factor authentication for most access; encryption of ePHI at rest and in transit, with limited exceptions; vulnerability scanning at least every six months and penetration testing at least every 12 months; network segmentation; a requirement to restore critical systems within 72 hours of a loss; written incident response plans; annual compliance audits; and written verification from business associates, at least annually, that they have deployed required technical safeguards. "
         "Because it is only a proposed rule, the current Security Rule in 45 CFR 164.302-164.318 remains in force until HHS issues a final rule. Readers should check the Federal Register for the current status."),
    _doc(139, "us_onc_hti1_uscdi_dsi", "ONC HTI-1 Final Rule - USCDI Version 3 and Decision Support Interventions (Predictive AI Transparency)",
         "ASTP/ONC / HHS", "US", "regulator_guidance", "2024-01-09", "2024-02-08", "HTI-1 Final Rule, 89 FR 1192",
         "HTI-1", "https://www.healthit.gov/topic/laws-regulation-and-policy/health-data-technology-and-interoperability-certification-program",
         "ONC Health Data, Technology, and Interoperability (HTI-1) Final Rule, published 9 January 2024, effective 8 February 2024: Updates the ONC Health IT Certification Program. "
         "It adopts USCDI version 3 as the baseline standard for certified health IT, replacing USCDI v1, with a compliance date of 1 January 2026. "
         "It replaces the older Clinical Decision Support criterion with a decision support interventions (DSI) criterion that requires certified health IT developers to give users transparency about predictive models, including algorithmic AI: source attributes such as the intended use, training data and cautions on bias and fairness (31 source attributes for predictive DSIs), plus intervention risk management practices for validity, reliability, safety, security and privacy. "
         "It also requires FHIR-based API capabilities aligned with the HL7 FHIR US Core Implementation Guide and SMART App Launch, and adds a Patient Demographics and Observations criterion. "
         "HTI-1 also updated information blocking exceptions."),
    _doc(140, "us_cms_interoperability_patient_access", "CMS Interoperability and Patient Access Rules - FHIR Patient Access API and Prior Authorization API (CMS-9115-F, CMS-0057-F)",
         "Centers for Medicare & Medicaid Services", "US", "regulator_guidance", "2024-02-08", "2024-04-08", "CMS-9115-F (2020); CMS-0057-F (2024)",
         "CMS-9115-F, CMS-0057-F", "https://www.cms.gov/priorities/key-initiatives/burden-reduction/interoperability/policies-and-regulations/cms-interoperability-and-prior-authorization-final-rule-cms-0057-f",
         "CMS interoperability rules: The CMS Interoperability and Patient Access final rule (CMS-9115-F, 2020) requires CMS-regulated payers, including Medicare Advantage organisations, Medicaid and CHIP agencies and managed care plans, and qualified health plan issuers on federally facilitated exchanges, to provide a FHIR R4 Patient Access API that gives members their claims, encounter and clinical data, using the HL7 FHIR US Core profiles and SMART on FHIR authorisation. "
         "The Interoperability and Prior Authorization final rule (CMS-0057-F), published February 2024, extends this: payers must implement Provider Access, Payer-to-Payer and Prior Authorization APIs built on FHIR; must send prior authorization decisions within 72 hours for expedited requests and seven calendar days for standard requests starting in 2026; must give specific reasons for denials; and must publicly report prior authorization metrics. "
         "The API requirements apply from 1 January 2027. The rules complement HIPAA's right of access and ONC's information blocking rules."),
    _doc(141, "us_tefca", "TEFCA - Trusted Exchange Framework and Common Agreement (QHINs and Exchange Purposes)",
         "ASTP/ONC / HHS", "US", "regulator_guidance", "2024-07-01", "2024-07-01", "Common Agreement v2.0",
         "TEFCA", "https://www.healthit.gov/topic/interoperability/policy/trusted-exchange-framework-and-common-agreement-tefca",
         "TEFCA (Trusted Exchange Framework and Common Agreement): A nationwide framework for health information exchange established by the 21st Century Cures Act, run by ONC (now ASTP/ONC) with the Recognized Coordinating Entity (RCE), The Sequoia Project. "
         "Qualified Health Information Networks (QHINs) are designated networks that connect to each other under the Common Agreement; participants and subparticipants such as providers, payers, public health agencies and individual access services connect through QHINs. "
         "Permitted exchange purposes are: treatment, payment, health care operations, public health, government benefits determination, and individual access services. "
         "Common Agreement version 2.0, released in 2024, adds support for FHIR-based exchange. TEFCA participants that are HIPAA covered entities or business associates remain subject to HIPAA; non-HIPAA participants must agree to comply with HIPAA-like privacy and security requirements and breach notification. "
         "Comparable cross-border arrangement in the EU: MyHealth@EU under the European Health Data Space."),
    _doc(142, "us_hhs_405d_hicp", "HHS 405(d) Health Industry Cybersecurity Practices (HICP) - Threats and Practices",
         "HHS 405(d) Program", "US", "regulator_guidance", "2023-01-01", "2023-01-01", "HICP 2023 Edition",
         "HICP", "https://405d.hhs.gov/",
         "Health Industry Cybersecurity Practices (HICP), the HHS 405(d) programme's voluntary cybersecurity guidance for healthcare organisations, developed under section 405(d) of the Cybersecurity Act of 2015: Identifies the five most common threats as email phishing attacks, ransomware attacks, loss or theft of equipment or data, insider, accidental or intentional data loss, and attacks against network-connected medical devices. "
         "Recommends ten cybersecurity practices: email protection systems; endpoint protection systems; access management; data protection and loss prevention; asset management; network management; vulnerability management; security operations centre and incident response; network connected medical devices; and cybersecurity oversight and governance. "
         "Separate technical volumes cover small, medium and large organisations. Under the HITECH Act amendment of 2021 (Public Law 116-321), HHS must consider whether a covered entity or business associate has had recognized security practices in place for the previous 12 months, such as HICP or the NIST Cybersecurity Framework, when determining HIPAA penalties and audits."),

    # ---- US technical standards (rank 3) ----
    _doc(143, "us_nist_sp800_66r2", "NIST SP 800-66 Revision 2 - Implementing the HIPAA Security Rule: A Cybersecurity Resource",
         "NIST", "US", "official_technical_standard", "2024-02-14", "2024-02-14", "SP 800-66r2",
         "NIST SP 800-66r2", "https://csrc.nist.gov/pubs/sp/800/66/r2/final",
         "NIST Special Publication 800-66 Revision 2, 'Implementing the HIPAA Security Rule: A Cybersecurity Resource' (February 2024): Guides regulated entities in applying the HIPAA Security Rule using NIST's risk management methods. "
         "It maps each Security Rule standard and implementation specification to NIST Cybersecurity Framework subcategories, to SP 800-53 security controls and to SP 800-171 requirements, and gives sample questions for assessing compliance. "
         "It follows the SP 800-30 risk assessment steps: prepare for the assessment, identify the scope and where ePHI is created, received, maintained or transmitted, identify threats and vulnerabilities, assess current controls, determine likelihood and impact, and determine risk levels. "
         "The publication uses the NIST Risk Management Framework to select, implement and monitor controls, and recommends documenting results. It is voluntary guidance, not a legal requirement, but its use is evidence of recognised security practices."),
    _doc(144, "us_nist_csf_2", "NIST Cybersecurity Framework 2.0 - Govern, Identify, Protect, Detect, Respond, Recover",
         "NIST", "US", "official_technical_standard", "2024-02-26", "2024-02-26", "CSF 2.0",
         "NIST CSF 2.0", "https://www.nist.gov/cyberframework",
         "NIST Cybersecurity Framework (CSF) 2.0, released 26 February 2024: A voluntary framework of outcomes for managing cybersecurity risk, applicable to organisations of all sizes and sectors, including healthcare. "
         "CSF 2.0 organises outcomes into six Functions: Govern (new in 2.0: cybersecurity risk management strategy, roles, policy and oversight), Identify (asset management, risk assessment, improvement), Protect (identity management and access control, awareness and training, data security, platform security, technology infrastructure resilience), Detect (continuous monitoring, adverse event analysis), Respond (incident management, analysis, reporting, communication and mitigation) and Recover (incident recovery plan execution and communication). "
         "It uses Profiles to describe current and target cybersecurity posture and Tiers to characterise rigour of risk management. "
         "Healthcare organisations commonly use the CSF to document recognised security practices alongside HIPAA Security Rule compliance and HHS 405(d) HICP."),
    _doc(145, "us_nist_ai_rmf", "NIST AI Risk Management Framework 1.0 and Generative AI Profile (NIST AI 600-1)",
         "NIST", "US", "official_technical_standard", "2023-01-26", "2023-01-26", "AI RMF 1.0; AI 600-1 (July 2024)",
         "NIST AI RMF", "https://www.nist.gov/itl/ai-risk-management-framework",
         "NIST AI Risk Management Framework (AI RMF 1.0), released 26 January 2023: A voluntary framework for managing risks of AI systems to individuals, organisations and society. "
         "Its core has four functions: Govern (a cross-cutting culture of risk management, accountability and policies), Map (establish context and identify risks), Measure (analyse, assess and track risks with quantitative and qualitative methods) and Manage (prioritise and act on risks). "
         "Characteristics of trustworthy AI in the framework are: valid and reliable; safe; secure and resilient; accountable and transparent; explainable and interpretable; privacy-enhanced; and fair with harmful bias managed. "
         "In July 2024 NIST published the Generative AI Profile (NIST AI 600-1), which lists risks specific to generative AI, including confabulation (hallucination), data privacy, information integrity, and harmful bias, and suggested actions. "
         "In US healthcare, the AI RMF supports compliance with FDA expectations for AI-enabled devices and ONC's decision support intervention transparency requirements, and parallels the EU AI Act's risk-based approach."),
    _doc(146, "us_fhir_us_core", "HL7 FHIR US Core Implementation Guide - Profiles Based on USCDI",
         "HL7 International", "US", "official_technical_standard", "2024-06-01", "2024-06-01", "US Core 6.1.0 (USCDI v3), 7.0.0 (USCDI v4)",
         "US Core IG", "https://hl7.org/fhir/us/core/",
         "HL7 FHIR US Core Implementation Guide: The US national baseline of FHIR R4 profiles, extensions and search parameters for exchanging the US Core Data for Interoperability (USCDI), required by ONC certification and used by CMS and payer APIs. "
         "Key profiles include US Core Patient (identifier, name, gender, birth date, and the must-support extensions race, ethnicity and birth sex), AllergyIntolerance, Condition, Encounter, Immunization, MedicationRequest, Observation (with laboratory, vital signs, smoking status and social history variants), Procedure and DocumentReference. "
         "US Core 6.1.0 aligns with USCDI v3, the version required by HTI-1 from 1 January 2026; US Core 7.0.0 aligns with USCDI v4. "
         "US Core is the US counterpart of the UK Core profiles used in NHS England and the European EHDS patient summary profiles. US servers support the RESTful interactions read and search, and are authorised with SMART App Launch OAuth 2.0 scopes."),
    _doc(147, "us_smart_on_fhir", "SMART on FHIR App Launch - OAuth 2.0 Authorization for Health Apps",
         "HL7 International", "US", "official_technical_standard", "2024-01-01", "2024-01-01", "SMART App Launch 2.2.0",
         "SMART App Launch", "https://hl7.org/fhir/smart-app-launch/",
         "SMART on FHIR (SMART App Launch Implementation Guide): The standard authorisation framework for apps that access FHIR data, built on OAuth 2.0 and OpenID Connect. "
         "Two launch flows: EHR launch, where an app is launched from inside an EHR session and receives context such as the patient and encounter; and standalone launch, where the app starts outside the EHR, for example a patient-facing app, and the user chooses a patient. "
         "Scopes limit access, in the syntax patient/Observation.read for a single patient's observations, user/Patient.rs for resources accessible to the user, and system scopes for backend services. Version 2 scopes use CRUDS letters (create, read, update, delete, search). "
         "Apps discover server endpoints at /.well-known/smart-configuration. Public client apps should use PKCE (Proof Key for Code Exchange), and confidential clients authenticate with asymmetric keys. "
         "SMART on FHIR is the authorisation layer required for certified patient access APIs under ONC and CMS rules."),
    _doc(148, "us_uscdi", "USCDI - United States Core Data for Interoperability",
         "ASTP/ONC / HHS", "US", "official_technical_standard", "2024-07-01", "2024-07-01", "USCDI v5",
         "USCDI", "https://www.healthit.gov/isp/united-states-core-data-interoperability-uscdi",
         "USCDI (United States Core Data for Interoperability): A standardised set of health data classes and data elements for nationwide, interoperable health information exchange, maintained by ASTP/ONC and expanded each year through a public process. "
         "Data classes include allergies and intolerances, assessment and plan of treatment, care team members, clinical notes, goals, health concerns, immunisations, laboratory, medications, patient demographics, problems, procedures, provenance, and vital signs. "
         "Version history: USCDI v1 is the baseline of the 2015 Edition certification and the Cures Act EHI definition; v2 (July 2021); v3 (July 2022) adds health insurance information, sexual orientation and gender identity and other items, and is required by HTI-1 from 1 January 2026; v4 (July 2023) adds clinical notes and facility data; v5 (July 2024) adds more elements. "
         "USCDI is implemented in FHIR through the US Core profiles. It is the US analogue of the European patient summary dataset in the EHDS."),

    # ---- Cross-border and comparative ----
    _doc(149, "eu_us_data_privacy_framework", "EU-US Data Privacy Framework - Adequacy Decision for Transfers of Personal Data to the US",
         "European Commission", "EU", "primary_law", "2023-07-10", "2023-07-10", "Commission Implementing Decision (EU) 2023/1795",
         "Implementing Decision 2023/1795", "https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023D1795",
         "EU-US Data Privacy Framework (DPF), adopted by the European Commission on 10 July 2023 as Implementing Decision (EU) 2023/1795 under GDPR Article 45: Finds that the United States ensures an adequate level of protection for personal data transferred from the EU to US organisations that self-certify to the framework, so transfers to certified organisations need no further transfer tool such as standard contractual clauses. "
         "Eligible US organisations are those subject to the investigatory and enforcement powers of the Federal Trade Commission or the Department of Transportation. "
         "Certified organisations must follow the DPF Principles on notice, choice, accountability for onward transfer, security, data integrity and purpose limitation, access, and recourse, enforcement and liability, with special rules for sensitive data such as health data (opt-in consent for disclosure to a third party or use for a new purpose). "
         "The decision relies on US Executive Order 14086 of October 2022, which limits signals intelligence activities to what is necessary and proportionate and creates a Data Protection Review Court for redress. The decision is reviewed periodically and has been challenged before the EU courts. "
         "For EU health data going to a US recipient without DPF certification, GDPR Articles 46 and 49 transfer tools apply."),
    _doc(150, "compare_hipaa_vs_gdpr", "Comparison - HIPAA vs GDPR for Health Data (Scope, Legal Basis, Breach Notification, Penalties)",
         "HealRAG corpus summary", "Global", "secondary_commentary", "2025-06-01", "2025-06-01", "2025.06",
         "Comparison", "https://www.hhs.gov/hipaa/for-professionals/index.html",
         "HIPAA versus GDPR for health data, a summary comparison. Scope: HIPAA applies only to covered entities (health plans, clearinghouses, providers using standard electronic transactions) and their business associates, and protects PHI; the GDPR applies to every controller and processor processing personal data of people in the EU, and treats data concerning health as a special category under Article 9. "
         "Legal basis: HIPAA permits uses and disclosures for treatment, payment and health care operations without consent and requires authorization for most other purposes; the GDPR requires a lawful basis under Article 6 and, for health data, a condition under Article 9(2), such as explicit consent, healthcare provision under Article 9(2)(h), or public health under Article 9(2)(i). "
         "Breach notification: HIPAA allows up to 60 calendar days to notify individuals and HHS; the GDPR requires notifying the supervisory authority within 72 hours where feasible (Article 33) and individuals without undue delay when there is high risk (Article 34). "
         "De-identification versus anonymisation: HIPAA has a rules-based Safe Harbor and Expert Determination; the GDPR sets a risk-based test of whether a person is identifiable by means reasonably likely to be used, and pseudonymised data remains personal data. "
         "Individual rights: HIPAA grants access, amendment, accounting of disclosures and restriction; the GDPR adds erasure, portability, objection and rights concerning automated decisions. "
         "Penalties: HIPAA civil penalties follow culpability tiers, adjusted annually; GDPR fines reach EUR 20 million or 4 percent of worldwide annual turnover. "
         "Enforcement: HHS OCR for HIPAA; national supervisory authorities for the GDPR, with a private right of action for damages under GDPR Article 82 but not under HIPAA."),
]


